function simpleCalculator(num1, operator, num2) {
  let result;

  switch (operator) {
    case '+':
      result = num1 + num2;
      break;
    case '-':
      result = num1 - num2;
      break;
    case '*':
      result = num1 * num2;
      break;
    case '/':
      if (num2 === 0) {
        return null;
      }
      result = num1 / num2;
      break;
    default:
      return null;
  }
  return result;
}

const capitalizeFirstLetter = (str) => {
  if (typeof str !== 'string' || str.length === 0) {
    return str;
  }

  const words = str.split(' ');
  const capitalizedWords = [];

  for (let i = 0; i < words.length; i++) {
    const word = words[i];
    if (word.length > 0) {
      const firstChar = word.charAt(0).toUpperCase();
      const restOfString = word.slice(1).toLowerCase();
      capitalizedWords.push(firstChar + restOfString);
    } else {
      capitalizedWords.push('');
    }
  }

  return capitalizedWords.join(' ');
};

