function extractEmails(text) {
  const emailRegex = /[\w.-]+@[\w.-]+\.[\w]{2,3}/g;
  let matches = text.match(emailRegex);
  if (matches === null) {
    return [];
  }
  let uniqueEmails = [];
  for (let i = 0; i < matches.length; i++) {
    let email = matches[i];
    if (uniqueEmails.indexOf(email) === -1) {
      uniqueEmails.push(email);
    }
  }
  return uniqueEmails;
};

